import React, { useEffect, useState } from 'react';
import { FaPhone, FaMapMarkerAlt, FaClock, } from 'react-icons/fa';
import './footer.css';

const Footer = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const scrollPosition = window.scrollY + window.innerHeight;
      const pageHeight = document.documentElement.scrollHeight;

      // 300px before bottom - start showing (20% opacity)
      if (pageHeight - scrollPosition < 300) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <footer className={`footer ${isVisible ? 'visible' : ''}`}>
      <div className="footer-content">
        <div className="footer-section">
          <h3>Hotel Shyam</h3>
          <p>Authentic Indian cuisine since 1985</p>
        </div>

        <div className="footer-section">
          <h3>Quick Links</h3>
          <ul className="footer-links">
            <li><a href="/menu">Menu</a></li>
            <li><a href="/reservation">Reservations</a></li>
            <li><a href="/about">Our Story</a></li>
          </ul>
        </div>

        <div className="footer-section">
          <h3>Contact</h3>
          <p><FaPhone /> +91 9876543210</p>
          <p><FaMapMarkerAlt /> 123 Food Street, Mumbai</p>
          <p><FaClock /> Open: 11AM - 11PM</p>
        </div>
      </div>

      <div className="footer-bottom">
        <p>&copy; {new Date().getFullYear()} Hotel Shyam</p>
      </div>
    </footer>
  );
};

export default Footer;
